import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios'; // We don't use it yet, but it's ready

// We move our mock data here to simulate it coming from a backend
const mockEmployees = [
  { id: 'TCS101', name: 'Dr. Anjali Rao', title: 'Professor', department: 'Computer Science', email: 'arao@university.edu', status: 'Active' },
  { id: 'PHY102', name: 'Dr. Vikram Kumar', title: 'Associate Professor', department: 'Physics', email: 'vkumar@university.edu', status: 'Active' },
  { id: 'ADM003', name: 'Sunita Sharma', title: 'Administrative Coordinator', department: 'Admissions Office', email: 'ssharma@university.edu', status: 'Active' },
  { id: 'LIB004', name: 'Rajesh Singh', title: 'Head Librarian', department: 'Library', email: 'rsingh@university.edu', status: 'On Leave' },
  { id: 'MGT001', name: 'Dr. Priya Mehta', title: 'Dean of Arts & Commerce', department: 'Administration', email: 'pmehta@university.edu', status: 'Active' },
];

const EmployeeManagementPage = () => {
  // 1. Set up state variables
  // `employees` will hold our list of staff, it starts as an empty array
  const [employees, setEmployees] = useState([]);
  // `isLoading` will control our loading message
  const [isLoading, setIsLoading] = useState(true);

  // 2. useEffect hook to fetch data when the component loads
  useEffect(() => {
    // This function simulates fetching data from an API
    const fetchEmployees = () => {
      console.log("Fetching employee data...");
      // --- In the future, you will replace this with a real axios call ---
      // Example: axios.get('http://127.0.0.1:8000/api/employees/')
      //          .then(response => {
      //              setEmployees(response.data);
      //              setIsLoading(false);
      //          });

      // Simulate a 1-second network delay
      setTimeout(() => {
        setEmployees(mockEmployees); // Put the mock data into our state
        setIsLoading(false); // Hide the loading message
        console.log("Data fetched successfully!");
      }, 1000); 
    };

    fetchEmployees();
  }, []); // The empty array [] means this effect runs only ONCE when the component mounts

  return (
    <>
      <header className="bg-card-light dark:bg-card-dark p-4 flex justify-between items-center border-b border-border-light dark:border-border-dark sticky top-0">
        <h1 className="text-2xl font-semibold text-text-light dark:text-text-dark">Staff & Faculty Directory</h1>
        <Link 
          to="/add-employee" 
          className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center hover:bg-blue-600"
        >
          <span className="material-icons mr-2 text-base">add</span> Add New Staff
        </Link>
      </header>

      <div className="p-8">
        <div className="bg-card-light dark:bg-card-dark p-6 rounded-lg shadow-md">
          {/* 3. Conditional Rendering: Show loading message or table */}
          {isLoading ? (
            <div className="text-center py-8">
              <p className="text-subtext-light dark:text-subtext-dark">Loading staff data...</p>
            </div>
          ) : (
            <table className="w-full text-sm text-left">
              <thead className="text-xs text-subtext-light dark:text-subtext-dark uppercase bg-background-light dark:bg-background-dark">
                <tr>
                  <th className="px-6 py-3">Staff ID</th>
                  <th className="px-6 py-3">Name</th>
                  <th className="px-6 py-3">Title / Designation</th>
                  <th className="px-6 py-3">Department</th>
                  <th className="px-6 py-3">Status</th>
                  <th className="px-6 py-3 text-center">Actions</th>
                </tr>
              </thead>
              <tbody>
                {employees.map((employee) => (
                  <tr key={employee.id} className="border-b border-border-light dark:border-border-dark hover:bg-gray-50 dark:hover:bg-gray-800/50">
                    <td className="px-6 py-4 font-medium text-text-light dark:text-text-dark">{employee.id}</td>
                    <td className="px-6 py-4 font-medium text-text-light dark:text-text-dark">
  <Link to={`/employees/${employee.id}`} className="hover:text-primary">
    {employee.name}
  </Link>
</td>
                    <td className="px-6 py-4">{employee.title}</td>
                    <td className="px-6 py-4">{employee.department}</td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-1 text-xs font-semibold rounded-full ${employee.status === 'Active' ? 'bg-green-100 text-green-800' : 'bg-yellow-100 text-yellow-800'}`}>
                        {employee.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <button className="text-primary hover:text-blue-700">Edit</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </>
  );
};

export default EmployeeManagementPage;
